      "source": [
        {
          "title": "OGC 06-103r4 Simple Feature Access - Part 1: Common Architecture",
          "link": "https://www.ogc.org/standards/sfa/"
        }
      ]
    },
    {
      "id": "https://geolabs.github.io/bblocks-generic-profiles/def/data-type/surface",
